CREATE TABLE IF NOT EXISTS customers ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', business_number TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', store_phone TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '', price_group TEXT NOT NULL DEFAULT 'A', auth_salt TEXT NOT NULL DEFAULT '', auth_hash TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS idx_customers_region ON customers(region, code);
CREATE TABLE IF NOT EXISTS customer_sessions ( token_hash TEXT PRIMARY KEY, customer_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), last_seen_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_customer_sessions_customer ON customer_sessions(customer_id, expires_at);
CREATE TABLE IF NOT EXISTS orders ( id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'app', status TEXT NOT NULL DEFAULT 'received', region_snapshot TEXT NOT NULL DEFAULT '', total_amount INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), printed_at TEXT, shipped_at TEXT, cancelled_at TEXT, FOREIGN KEY(customer_id) REFERENCES customers(id) );
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_region_status ON orders(region_snapshot, status, printed_at, created_at);
CREATE TABLE IF NOT EXISTS order_items ( id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, product_id TEXT NOT NULL, product_name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT '', option_label TEXT NOT NULL, quantity REAL NOT NULL, unit_price INTEGER NOT NULL DEFAULT 0, tax_type TEXT NOT NULL DEFAULT 'taxable', warehouse_zone TEXT NOT NULL DEFAULT '', FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id, id);
CREATE INDEX IF NOT EXISTS idx_order_items_product ON order_items(product_id, order_id);
CREATE TABLE IF NOT EXISTS inventory_stock ( product_id TEXT NOT NULL, option_label TEXT NOT NULL, quantity REAL NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(product_id, option_label), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS inventory_ledger ( id INTEGER PRIMARY KEY AUTOINCREMENT, product_id TEXT NOT NULL, option_label TEXT NOT NULL DEFAULT '', quantity_change REAL NOT NULL, event_type TEXT NOT NULL, reference_order_id TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(reference_order_id) REFERENCES orders(id) );
CREATE INDEX IF NOT EXISTS idx_inventory_ledger_product ON inventory_ledger(product_id, created_at DESC);
CREATE TABLE IF NOT EXISTS receivable_ledger ( id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id TEXT NOT NULL, amount INTEGER NOT NULL, event_type TEXT NOT NULL, reference_order_id TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(reference_order_id) REFERENCES orders(id) );
CREATE INDEX IF NOT EXISTS idx_receivable_customer ON receivable_ledger(customer_id, created_at DESC);
CREATE TABLE IF NOT EXISTS payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id TEXT NOT NULL, amount INTEGER NOT NULL, method TEXT NOT NULL DEFAULT 'bank', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(customer_id) REFERENCES customers(id) );
CREATE INDEX IF NOT EXISTS idx_payments_customer ON payments(customer_id, created_at DESC);
